  "claims": [
    {
      "claim": "Esaxerenone, the closest structural context sharing the methyl-amide-aryl and CF3/OCF3-bearing biaryl motif, had absolute oral bioavailability of 89.0% fasting and 90.8% postprandial in healthy subjects; an L4 Caco-2 record for esaxerenone shows high basal-to-apical permeability (43.5 ×10^-6 cm/s), consistent with high permeability but not a direct F measurement.",
      "card_ids": ["C01", "C02", "C10", "C11", "C12", "C20", "C26", "C54"]
    },
    {
      "claim": "Nilotinib, a lipophilic CF3-containing amide with precipitation-limited absorption, had absolute oral bioavailability of about 31% under fasted conditions, still above the 20% threshold.",
      "card_ids": ["C06", "C22", "C34"]
    },
    {
      "claim": "Elinzanetant, a lipophilic CF3-containing amide with a morpholine-type amine, had oral bioavailability of 36.7% and is described as orally bioavailable.",
      "card_ids": ["C15", "C17", "C23"]
    },
    {
      "claim": "L4/L5 permeability records for OCF3/CF3-containing amides and related lipophilic compounds show high Caco-2 permeability and low efflux ratios (e.g., esaxerenone 43.5, HSGN-238 82.3, DNDI-VL-2098 226 nm/s with ER 1.1, D4-9-31 ER 1.02), supporting adequate intestinal absorption; none of these are query-specific direct F measurements.",
      "card_ids": ["C49", "C51", "C53", "C50", "C57", "C63", "C69", "C60", "C65"]
    },
    {
      "claim": "Solubility/precipitation risk is a concern for the query (high logD 5.82), but no affirmative evidence shows F<20%; nilotinib's precipitation-limited F was 31%, and the L5 records do not reveal query-specific gut-wall efflux or intestinal metabolism.",
      "card_ids": ["C34", "C52", "C58", "C63", "C69"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C59", "C60", "C61", "C62", "C63", "C64", "C65", "C66", "C67", "C68", "C69", "C70"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "No query-specific solubility/dissolution or precipitation data are available; high logD is a physicochemical risk, not affirmative low-F evidence.",
    "No query-specific gut-wall efflux or intestinal metabolism measurements are available; L5 records are for reference molecules only.",
    "No query-specific first-pass or systemic clearance data are available.",
    "Condition matching is imperfect: the query has no reported external condition, while most contexts are fasted/fed/cirrhosis-specific.",
    "Closest analogs differ in polar substituents and formulation (e.g., esaxerenone sulfone vs query morpholine/OCF3; nilotinib different heteroaromatic core)."
  ],
  "decision_summary": "Prediction remains high: all transferable numeric gold records for structurally relevant amide/heteroaryl contexts are >=31%, with closest analogs esaxerenone (89-91%) and nilotinib (31%) supporting F>=20%; L5 gut-wall/efflux records for related lipophilic compounds show high permeability and low efflux but are not query-specific, and no affirmative evidence supports F<20%. Confidence remains moderate because no direct query measurement is available."
}

